      "path": "package.json",
      "content": "{\n  \"name\": \"billion-context\",\n  \"version\": \"0.1.215\",\n  \"description\": \"A context-compression plugin \\u2014 small context windows (a 100K context is enough), 5x fewer tokens, month-long single sessions (billions of tokens), and compression quality \\u2014 for all agents: pi, OpenCode, Codex, Claude Code, and more. billion-context is all you need.\",\n  \"type\": \"module\",\n  \"main\": \"dist/index.js\",\n  \"exports\": {\n    \".\": \"./dist/agent/dsh-native.js\",\n    \"./server\": \"./dist/agent/opencode-native.js\",\n    \"./dsh\": \"./dist/agent/dsh-native.js\",\n    \"./dsh-compaction-gate\": \"./dist/agent/dsh-compaction-gate.js\",\n    \"./package.json\": \"./package.json\",\n    \"./dsh/package.json\": \"./package.json\",\n    \"./client\": \"./dist/agent/dsh-native-client.js\"\n  },\n  \"bin\": {\n    \"bili\": \"./dist/index.js\",\n    \"bili-proxy\": \"./dist/index.js\"\n  },\n  \"scripts\": {\n    \"build\": \"npm --prefix kernel run build && npm --prefix pi-subagents run build && tsup && node scripts/write-build-info.mjs && node scripts/check-dist-import-annotations.mjs && node scripts/check-dist-external.mjs\",\n    \"prepare\": \"node scripts/check-dist-ready.mjs\",\n    \"registry:snapshot\": \"node scripts/update-registry-snapshot.mjs\",\n    \"codex-models:snapshot\": \"node scripts/update-codex-models-snapshot.mjs\",\n    \"pretypecheck\": \"npm --prefix kernel run build && npm --prefix pi-subagents run build\",\n    \"typecheck\": \"tsc --noEmit --project tsconfig.json\",\n    \"check:unused-exports\": \"node scripts/check-unused-exports.mjs\",\n    \"check:test-import-graph\": \"node scripts/check-test-import-graph.mjs\",\n    \"check:dist-thin\": \"node scripts/check-dist-thin-install.mjs\",\n    \"pretest\": \"node scripts/test-suite-lock.mjs gate && node scripts/ci-pretest-cache.mjs\",\n    \"test\": \"node scripts/test-suite-lock.mjs run\",\n    \"start\": \"node dist/index.js\",\n    \"test:e2e\": \"node --import ./tests/preload-test-env.mjs --import tsx --test tests/e2e/e2e-codex.test.ts\",\n    \"test:e2e:fake\": \"node --import ./tests/preload-test-env.mjs --import tsx --test tests/e2e/e2e-codex-fake.test.ts\",\n    \"test:e2e:image\": \"node --import ./tests/preload-test-env.mjs --import tsx --test tests/e2e/e2e-image-billing.test.ts\",\n    \"gate:local\": \"node scripts/release-gate-local.mjs\"\n  },\n  \"keywords\": [\n    \"context\",\n    \"compression\",\n    \"proxy\",\n    \"acp\",\n    \"ai\",\n    \"agent\",\n    \"claude-code\",\n    \"cursor\",\n    \"codex\",\n    \"aider\",\n    \"anthropic\",\n    \"openai\",\n    \"pi-package\"\n  ],\n  \"license\": \"MIT\",\n  \"author\": \"ranxianglei\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/ranxianglei/billion-context.git\"\n  },\n  \"homepage\": \"https://github.com/ranxianglei/billion-context#readme\",\n  \"bugs\": {\n    \"url\": \"https://github.com/ranxianglei/billion-context/issues\"\n  },\n  \"dependencies\": {\n    \"mysql2\": \"^3.15.3\",\n    \"zod\": \"4.6.7\"\n  },\n  \"optionalDependencies\": {\n    \"jimp\": \"1.6.1\"\n  },\n  \"devDependencies\": {\n    \"@deepseek-ai/cordis\": \"4.1.0\",\n    \"@earendil-works/pi-coding-agent\": \"0.83.0\",\n    \"@earendil-works/pi-tui\": \"0.83.0\",\n    \"@types/node\": \"^22.0.0\",\n    \"@types/node-forge\": \"^1.3.14\",\n    \"@types/semver\": \"^7.7.1\",\n    \"@types/ws\": \"8.18.2\",\n    \"acp-kernel\": \"file:./kernel\",\n    \"billion-context-pi-subagents\": \"file:./pi-subagents\",\n    \"esbuild\": \"^0.27.0\",\n    \"fzstd\": \"0.1.1\",\n    \"jsonc-parser\": \"^3.3.1\",\n    \"node-forge\": \"^1.4.0\",\n    \"prettier\": \"^3.3.0\",\n    \"semver\": \"7.8.5\",\n    \"tar\": \"^7.5.22\",\n    \"tsup\": \"^8.0.0\",\n    \"tsx\": \"^4.0.0\",\n    \"typebox\": \"^1.3.34\",\n    \"typescript\": \"^5.5.0\",\n    \"undici\": \"^7.29.0\",\n    \"verdaccio\": \"^6.10.4\",\n    \"ws\": \"8.22.0\",\n    \"z3-solver\": \"^5.3.1\"\n  },\n  \"engines\": {\n    \"node\": \">=20\"\n  },\n  \"files\": [\n    \"LICENSE\",\n    \"README.md\",\n    \"docs/configuration.md\",\n    \"docs/configuration.zh-CN.md\",\n    \"dist\",\n    \"dsh.bundle.patch.yml\",\n    \"hermes-plugin\",\n    \"paper/*.md\",\n    \"paper/figures/*.png\",\n    \"website/articles.json\",\n    \"website/blog/posts\"\n  ],\n  \"pi\": {\n    \"image\": \"https://raw.githubusercontent.com/ranxianglei/billion-context/master/docs/logo.png\",\n    \"extensions\": [\n      \"./dist/agent/billion-context.js\"\n    ]\n  },\n  \"publishConfig\": {\n    \"access\": \"public\",\n    \"registry\": \"https://registry.npmjs.org\"\n  },\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./dsh.bundle.patch.yml\"\n    },\n    \"client\": {\n      \"platform\": \"web\"\n    }\n  }\n}\n"
